def lines_starting(text, prefix):
    return [i for i, line in enumerate(text.split('\n')) if line.startswith(prefix)]


def line(text, prefix, new):
    """Replace the one whole line that starts with prefix."""
    lines = text.split('\n')
    hits = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(hits) == 1, (prefix[:70], len(hits))
    lines[hits[0]] = new
    return '\n'.join(lines)


def block(text, start, end, new):
    """Replace the lines from the one starting with start up to, not including,
    the first later line starting with end."""
    lines = text.split('\n')
    s = [i for i, l in enumerate(lines) if l.startswith(start)]
    assert len(s) == 1, (start[:70], len(s))
    e = [i for i, l in enumerate(lines) if l.startswith(end) and i > s[0]]
    assert e, end[:70]
    lines[s[0]:e[0]] = new.split('\n')
    return '\n'.join(lines)


def sub(text, old, new):
    assert text.count(old) == 1, (old[:70], text.count(old))
    return text.replace(old, new)


